import {project,unproject,inside,applyOverride,checkCollisions,createRecord,validateRecord,photoStore} from './survey-core.mjs';
const $=id=>document.getElementById(id),game=$('game'),KEY='matsuba-survey-v1';let win,map,originals,camera,photoURL,shotURL,photoBlob,selecting=false,active='school-front';
let record;try{record=JSON.parse(localStorage.getItem(KEY))||createRecord()}catch{record=createRecord()}
const status=text=>$('status').textContent=text;
const guard=fn=>async(...args)=>{try{await fn(...args)}catch(e){status('保存・操作できません: '+e.message)}};
function persist(){record.updatedAt=new Date().toISOString();localStorage.setItem(KEY,JSON.stringify(record))}
function download(data,name){const url=typeof data==='string'?data:URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download=name;a.click();if(typeof data!=='string')setTimeout(()=>URL.revokeObjectURL(url),1000)}
function currentLocation(){return record.locations.find(l=>l.id===active)}
function fieldsFromCamera(){const geo=unproject(map.origin,camera.x,camera.y);for(const key of ['lat','lon'])$(key).value=geo[key].toFixed(7);for(const key of ['height','heading','pitch','fov'])$(key).value=camera[key];$('readout').textContent=`緯度 ${geo.lat.toFixed(7)} / 経度 ${geo.lon.toFixed(7)}\n方位 ${camera.heading.toFixed(1)}° / 高さ ${camera.height}m\n建物ID ${$('building').value}`}
function setCamera(){win.kartSurveyRace.pause(true);win.kartSurveyScene.camera(camera);fieldsFromCamera()}
function getCamera(){const lat=+$('lat').value,lon=+$('lon').value,values=Object.fromEntries(['height','heading','pitch','fov'].map(k=>[k,+$(k).value]));if(![lat,lon,...Object.values(values)].every(Number.isFinite)||values.height<.5||values.height>500||values.fov<15||values.fov>110||Math.abs(values.pitch)>89)throw Error('カメラの値が範囲外です');const [x,y]=project(map.origin,lat,lon);if(Math.abs(x)>2400||Math.abs(y)>2000)throw Error('地図の収録範囲外です');return {x,y,...values}}
function selectBuilding(){const b=originals.get($('building').value),e=record.overrides[b.id]||{},current=applyOverride(b,e);$('buildingHeight').value=current.height;$('levels').value=current.levels;const appearance=win.KART_BUILDING_COLORS.resolve(current);$('wall').value=appearance.wall;$('roof').value=appearance.roof;$('roofShape').value=current.roofShape;$('use').value=current.type;$('material').value=current.wallMaterial||'unknown';$('rotation').value=e.rotation||0;$('east').value=e.offset?.[0]||0;$('north').value=e.offset?.[1]||0;$('footprint').value=JSON.stringify(e.p||b.p);$('holes').value=JSON.stringify(e.holes||b.holes);$('features').value=JSON.stringify(e.features||[]);for(const k of ['position','shape','color'])$(k+'Quality').value=e.quality?.[k]||'unverified';$('reviewStatus').value=e.quality?.status||'unverified';$('reviewNote').value=e.quality?.note||'';$('evidence').textContent=`${b.name||'名称未確認'} / 出典 ${b.source}\n${JSON.stringify(b.evidence)}\n輪郭は実地図。高さ・外観の推定を含みます。`;fieldsFromCamera()}
function applyAll(){const candidates=new Map();for(const [id,e] of Object.entries(record.overrides))candidates.set(id,applyOverride(originals.get(id),e));const temporary={...map,buildings:map.buildings.map(b=>candidates.get(b.id)||structuredClone(originals.get(b.id)))};for(const [id,b] of candidates){const e=record.overrides[id];if(e.p||e.holes||e.rotation||e.offset?.some(Boolean))checkCollisions(b,temporary)}map.buildings.splice(0,map.buildings.length,...temporary.buildings);win.kartSurveyScene.refresh()}
function refreshLocations(){const selector=$('locations');selector.replaceChildren();for(const l of record.locations){const o=document.createElement('option');o.value=l.id;o.textContent=l.name+(l.reference?' · 資料あり':' · 未確認');selector.append(o)}selector.value=active}
async function loadLocation(){active=$('locations').value;const l=currentLocation();camera={...l.camera};setCamera();$('locationName').value=l.name;$('source').value=l.reference?.source||'';$('date').value=l.reference?.date||'';$('referenceType').value=l.reference?.type||'ground';$('referenceNote').value=l.reference?.note||'';photoBlob=await photoStore('get',active);showPhoto(photoBlob);if(l.buildingId&&originals.has(l.buildingId)){$('building').value=l.buildingId;selectBuilding()}status(l.reference?(photoBlob?'地点と資料を読み込みました。未確認項目は自動認定しません。':'出典記録はありますが、この端末に写真原本がありません。登録してください。'):'参考写真は未登録です。')}
function showPhoto(blob){if(photoURL)URL.revokeObjectURL(photoURL);photoURL=blob?URL.createObjectURL(blob):null;$('photo').removeAttribute('src');if(photoURL)$('photo').src=photoURL;game.style.width='100%';game.style.height='100%';if(photoURL){const image=new Image();image.onload=()=>{const box=$('view').getBoundingClientRect(),ratio=image.width/image.height;let width=box.width,height=width/ratio;if(height>box.height){height=box.height;width=height*ratio}game.style.width=width+'px';game.style.height=height+'px'};image.src=photoURL}}
function capture(){shotURL=win.kartSurveyScene.capture();$('shot').src=shotURL;status('比較画面を撮影しました。カメラ条件は地点保存で残せます。')}
for(const k of ['position','shape','color'])$(k+'Quality').innerHTML='<option value="unverified">未確認</option><option value="mismatch">不一致</option><option value="approximate">概ね一致</option><option value="matched">資料上で一致</option>';
$('pause').onclick=guard(()=>{const me=win.kartSurveyRace.pause(true);camera={x:me.x,y:me.y,height:1.6,heading:(90-me.h*180/Math.PI+360)%360,pitch:0,fov:60};setCamera();status('レースとアイテム時間を停止しました。')});
$('resume').onclick=guard(()=>{win.kartSurveyScene.camera(null);win.kartSurveyRace.pause(false);$('comparison').style.display='none';game.style.width=game.style.height='100%';status('元の走行位置からレースを再開しました。')});
$('jump').onclick=guard(()=>{camera=getCamera();setCamera()});
for(const b of document.querySelectorAll('[data-move]'))b.onclick=guard(()=>{camera=getCamera();const h=camera.heading*Math.PI/180,mode=b.dataset.move,angle=h+(mode==='back'?Math.PI:mode==='left'?-Math.PI/2:mode==='right'?Math.PI/2:0);camera.x+=Math.sin(angle)*2;camera.y+=Math.cos(angle)*2;setCamera()});
$('capture').onclick=guard(capture);$('downloadShot').onclick=guard(()=>{capture();download(shotURL,'matsuba-'+active+'.png')});
$('locations').onchange=guard(loadLocation);
$('newLocation').onclick=guard(async()=>{const me=win.kartSurveyRace.state();if(!camera)camera={x:me.x,y:me.y,height:1.6,heading:0,pitch:0,fov:60};active='location-'+crypto.randomUUID();record.locations.push({id:active,name:'未確認地点',camera:{...camera},quality:{status:'unverified'}});persist();refreshLocations();await loadLocation()});
$('upload').onchange=guard(async()=>{const file=$('upload').files[0];if(!file)return;if(file.size>25*1024*1024)throw Error('写真は25MB以下にしてください');const bitmap=await createImageBitmap(file);bitmap.close();await photoStore('put',active,file);photoBlob=file;showPhoto(file);status('写真を端末に保存しました。出典と撮影条件も保存してください。')});
$('deletePhoto').onclick=guard(async()=>{await photoStore('delete',active);photoBlob=null;showPhoto(null);delete currentLocation().reference;persist();refreshLocations();status('写真と資料登録を削除しました。')});
$('saveLocation').onclick=guard(()=>{const l=currentLocation();l.name=$('locationName').value||'名称未確認';l.camera=getCamera();l.buildingId=$('building').value;if(photoBlob)l.reference={source:$('source').value,date:$('date').value||null,type:$('referenceType').value,note:$('referenceNote').value,photoStoredLocally:true};persist();refreshLocations();status('地点・撮影条件・出典を保存しました。')});
for(const [id,mode] of [['side','pair'],['overlay','overlay']])$(id).onclick=guard(()=>{if(!photoURL)throw Error('参考写真を登録してください');capture();$('comparison').className=mode;$('comparison').style.display=mode==='pair'?'grid':'block';$('photo').style.opacity=mode==='overlay'?$('alpha').value:1});
$('live').onclick=()=>$('comparison').style.display='none';$('alpha').oninput=()=>{if($('comparison').className==='overlay')$('photo').style.opacity=$('alpha').value};
$('building').onchange=selectBuilding;
$('pick').onclick=()=>{selecting=true;$('comparison').style.display='none';status('ゲーム画面で建物をクリックしてください。地面投影で選択するため、見下ろしカメラを推奨します。')};
$('saveBuilding').onclick=guard(()=>{const id=$('building').value,quality={position:$('positionQuality').value,shape:$('shapeQuality').value,color:$('colorQuality').value,status:$('reviewStatus').value,note:$('reviewNote').value,locationId:active,reference:currentLocation().reference||null};if((quality.status==='reviewed'||['matched','approximate'].some(s=>[quality.position,quality.shape,quality.color].includes(s)))&&(!quality.reference?.source||!quality.note||quality.reference.type==='test'))throw Error('照合済み・一致には現地資料の出典と確認根拠が必要です');const edit={height:+$('buildingHeight').value,levels:+$('levels').value,wallColor:$('wall').value,roofColor:$('roof').value,roofShape:$('roofShape').value,type:$('use').value,wallMaterial:$('material').value,rotation:+$('rotation').value,offset:[+$('east').value,+$('north').value],p:JSON.parse($('footprint').value),holes:JSON.parse($('holes').value),features:JSON.parse($('features').value),quality};const old=record.overrides[id];record.overrides[id]=edit;try{applyAll();persist()}catch(e){if(old)record.overrides[id]=old;else delete record.overrides[id];applyAll();throw e}status('建物 '+id+' の修正・確認状況を保存しました。');selectBuilding()});
$('revert').onclick=guard(()=>{delete record.overrides[$('building').value];applyAll();persist();selectBuilding();status('元の建物に戻しました。')});
$('export').onclick=()=>download(new Blob([JSON.stringify(record,null,2)],{type:'application/json'}),'matsuba-survey.json');
$('import').onchange=guard(async()=>{const file=$('import').files[0];if(!file)return;const incoming=validateRecord(JSON.parse(await file.text()),[...originals.values()]),old=record;if(!incoming.locations.length)throw Error('地点がありません');record=incoming;try{applyAll();persist()}catch(e){record=old;applyAll();throw e}if(!record.locations.length)throw Error('地点がありません');active=record.locations[0].id;refreshLocations();await loadLocation();status('JSONを読み込みました。写真原本は別途登録してください。')});
async function init(){const html=await (await fetch('./index.html')).text();game.srcdoc=html.replace('<head>','<head><base href="'+new URL('.',location.href).href+'"><script>window.KART_SURVEY=true;<\/script>');await new Promise(resolve=>{const poll=setInterval(()=>{win=game.contentWindow;if(win.kartSurveyScene&&win.kartSurveyRace){clearInterval(poll);resolve()}},100);setTimeout(()=>{clearInterval(poll);if(!win?.kartSurveyScene)status('3D照合機能を起動できません。WebGL対応ブラウザで再読み込みしてください。')},30000)});win.document.querySelector('#startBtn').click();map=win.REAL_HACHIMAN;originals=new Map(map.buildings.map(b=>[b.id,structuredClone(b)]));validateRecord(record,map.buildings);if(!record.locations.length){const p=map.route[0];record.locations.push({id:'school-front',name:'八幡中学校前 · 第1照合地点',buildingId:'gsi/38549eb19a63f49c',camera:{x:p[0],y:p[1],height:1.6,heading:300,pitch:0,fov:60},quality:{status:'unverified'}});for(const b of map.buildings.filter(b=>b.name&&b.routeDistance<30).slice(0,16))record.locations.push({id:'landmark-'+b.id,name:b.name+' · 地図上の目印／外観未確認',buildingId:b.id,camera:{x:b.centroid[0]+20,y:b.centroid[1]-20,height:1.6,heading:315,pitch:0,fov:60},quality:{status:'unverified'}});persist()}active=record.locations[0].id;const selector=$('building');for(const b of [...map.buildings].sort((a,b)=>Math.hypot(...a.centroid)-Math.hypot(...b.centroid))){const o=document.createElement('option');o.value=b.id;o.textContent=(b.name||b.type)+' · '+b.id;selector.append(o)}
win.document.addEventListener('pointerdown',guard(e=>{if(!selecting||e.target.tagName!=='CANVAS')return;const p=win.kartSurveyScene.groundPoint(e.clientX,e.clientY);if(!p)return;const b=map.buildings.find(b=>inside(p,b.p)&&!b.holes.some(r=>inside(p,r)));if(b){$('building').value=b.id;selectBuilding();selecting=false;status('選択: '+b.id)}else status('建物の輪郭内をクリックしてください。')}));refreshLocations();applyAll();await loadLocation()}
guard(init)();
